<?php require_once __DIR__.'/../../app/layout.php';$a=require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action'];if(in_array($action,['approve','reject','activate','deactivate'],true)){$status=$action==='approve'||$action==='activate'?'active':($action==='reject'?'rejected':'inactive');$memberId=$status==='active'?'TSSMT'.str_pad((string)$id,6,'0',STR_PAD_LEFT):null;$pdo->prepare('UPDATE members SET status=?,member_id=COALESCE(member_id,?),approved_at=IF(?="active",NOW(),approved_at) WHERE id=?')->execute([$status,$memberId,$status,$id]);if($status==='active'){$s=$pdo->prepare('SELECT password_hash FROM members WHERE id=?');$s->execute([$id]);if(!$s->fetchColumn())$pdo->prepare('UPDATE members SET password_hash=? WHERE id=?')->execute([password_hash(bin2hex(random_bytes(6)),PASSWORD_DEFAULT),$id]);}audit($pdo,$a['id'],'member_'.$action,'member',$id);flash('Member updated.');redirect('/admin/members.php');}}$q=trim($_GET['q']??'');$s=$pdo->prepare('SELECT * FROM members WHERE full_name LIKE ? OR email LIKE ? OR mobile LIKE ? ORDER BY created_at DESC');$s->execute(array_fill(0,3,'%'.$q.'%'));header_html('Members');?><h1>Members</h1><form method="get"><input name="q" value="<?=e($q)?>" placeholder="Search name, email or mobile"><button>Search</button></form><table><tr><th>Name</th><th>Member ID</th><th>Status</th><th>Actions</th></tr><?php foreach($s as $m):?><tr><td><?=e($m['full_name'])?><br><?=e($m['email'])?></td><td><?=e($m['member_id'])?></td><td><?=e($m['status'])?></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$m['id']?>"><?php if($m['status']==='pending'):?><button name="action" value="approve">Approve</button><button name="action" value="reject">Reject</button><?php else:?><button name="action" value="<?= $m['status']==='active'?'deactivate':'activate'?>"><?= $m['status']==='active'?'Deactivate':'Activate'?></button><?php endif;?></form></td></tr><?php endforeach;?></table><?php footer_html();
